arguments.new_string:
        # Cap at 1.0
        return min(1.0, combined_score)


def is_suspicious_description(description: str, api_key: str | None = None) -> bool:
    """
    Use OpenAI GPT-4o to analyze a transaction description for suspicious content.

    Args:
        description: The transaction description to analyse.
        api_key: OpenAI API key.  Falls back to the OPENAI_API_KEY env var.

    Returns:
        True if the model flags the description as suspicious, False otherwise.
    """
    key = api_key or os.environ.get("OPENAI_API_KEY")
    if not key:
        raise ValueError(
            "No OpenAI API key provided. Pass api_key or set OPENAI_API_KEY."
        )

    system_prompt = (
        "You are a fraud-detection analyst. "
        "Given a transaction description, decide whether it looks suspicious "
        "(e.g. phishing, money laundering, scam, dark-web marketplace, "
        "unusual keyword obfuscation).  Respond with exactly YES or NO."
    )

    payload = {
        "model": "gpt-4o",
        "messages": [
            {"role": "system", "content": system_prompt},
            {
                "role": "user",
                "content": f"Transaction description: \"{description}\"",
            },
        ],
        "temperature": 0,
        "max_tokens": 5,
    }

    response = requests.post(
        "https://api.openai.com/v1/chat/completions",
        headers={
            "Authorization": f"Bearer {key}",
            "Content-Type": "application/json",
        },
        json=payload,
        timeout=30,
    )
    response.raise_for_status()

    answer = response.json()["choices"][0]["message"]["content"].strip().upper()
    return answer.startswith("YES")
